const fs = require('fs-extra');
const path = require('path');
const logger = require('../utils/logger');
const { sanitizeFilename, formatFileSize } = require('../utils/pathUtils');
const config = require('../config');

/**
 * Find output files in the MDE4CPP application/bin directory
 * Output files are generated by the build process and placed in application/bin/
 * 
 * File locations:
 * - Generated DLLs: MDE4CPP_HOME/application/bin/{ModelName}.dll
 * - Generated EXEs: MDE4CPP_HOME/application/bin/App_{ModelName}.exe
 * 
 * @param {string} modelName - Model name to search for
 * @returns {Promise<object>} Object with dlls and executables arrays
 */
async function findOutputFiles(modelName) {
    // Output files are always generated in MDE4CPP_HOME/application/bin/
    // Use absolute path for production reliability
    const binDir = path.resolve(config.mde4cpp.home, 'application', 'bin');
    const outputFiles = {
        dlls: [],
        executables: []
    };
    
    if (!await fs.pathExists(binDir)) {
        logger.warn(`Bin directory not found: ${binDir}`);
        logger.warn(`MDE4CPP_HOME: ${config.mde4cpp.home}`);
        return outputFiles;
    }
    
    try {
        const files = await fs.readdir(binDir);
        
        logger.debug(`Scanning ${files.length} files in ${binDir} for model: ${modelName}`);
        
        for (const file of files) {
            const filePath = path.join(binDir, file);
            const stats = await fs.stat(filePath);
            
            if (!stats.isFile()) continue;
            
            const lowerName = file.toLowerCase();
            const modelLower = modelName.toLowerCase();
            const fileBaseName = lowerName.replace(/\.(dll|exe)$/, ''); // Remove extension
            
            // Check for DLL files matching model name (case-insensitive)
            // Include PSSM Exec DLLs (ModelNameExec.dll) as they're part of PSSM model output
            // Exclude fUML execution libraries that don't match the model name pattern
            if (lowerName.endsWith('.dll')) {
                // Patterns to match:
                // - ModelName.dll
                // - ModelNamed.dll (debug version)
                // - ModelNameExec.dll (PSSM execution DLL)
                // Handle underscores and hyphens in model names
                const modelPattern = modelLower.replace(/[_-]/g, '[_-]?'); // Allow optional underscore/hyphen
                const exactMatch = new RegExp(`^${modelPattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(d|exec)?$`);
                const startsWithMatch = fileBaseName.startsWith(modelLower) || 
                                       fileBaseName.startsWith(modelLower.replace(/[_-]/g, ''));
                
                // Check if file matches model name pattern
                const matchesModel = exactMatch.test(fileBaseName) || 
                                   (startsWithMatch && 
                                    (fileBaseName === modelLower || 
                                     fileBaseName === modelLower + 'd' || 
                                     fileBaseName === modelLower + 'exec' ||
                                     fileBaseName.endsWith('d') && fileBaseName.slice(0, -1) === modelLower ||
                                     fileBaseName.endsWith('exec') && fileBaseName.slice(0, -4) === modelLower));
                
                // For PSSM Exec DLLs, include them
                // For other Exec DLLs, only include if they match the model name exactly
                if (matchesModel) {
                    // Exclude fUML execution libraries that are generic (not model-specific)
                    // These typically have names like "fuml_exec.dll" without the model name
                    const isGenericExec = lowerName.includes('exec') && 
                                         !lowerName.includes(modelLower.replace(/[_-]/g, '')) &&
                                         !lowerName.match(new RegExp(modelLower.replace(/[_-]/g, '[_-]?')));
                    
                    if (!isGenericExec) {
                        outputFiles.dlls.push({
                            name: file,
                            path: filePath,
                            size: stats.size,
                            sizeFormatted: formatFileSize(stats.size),
                            createdAt: stats.birthtime.toISOString()
                        });
                        logger.debug(`Found DLL: ${file}`);
                    }
                }
            }
            
            // Check for executable files matching model name (case-insensitive)
            // Support multiple patterns: App_ModelName, App_modelName, App_ModelNamed
            // Also support direct model name executables for different model types
            if (lowerName.endsWith('.exe')) {
                const modelPascal = modelName.charAt(0).toUpperCase() + modelName.slice(1);
                const modelCamel = modelName.charAt(0).toLowerCase() + modelName.slice(1);
                
                // Check various executable naming patterns
                // Patterns: App_ModelName.exe, App_ModelNamed.exe, App_modelName.exe, etc.
                const appPrefixPattern = `app_${modelLower.replace(/[_-]/g, '[_-]?')}`;
                const matchesPattern = 
                    // App_ModelName patterns (with optional underscores/hyphens)
                    lowerName.match(new RegExp(`^${appPrefixPattern}(d)?\\.exe$`)) ||
                    lowerName.startsWith(`app_${modelLower}`) || 
                    lowerName.startsWith(`app_${modelLower}d`) ||
                    lowerName.startsWith(`app_${modelName.toLowerCase()}`) ||
                    lowerName.startsWith(`app_${modelPascal.toLowerCase()}`) ||
                    lowerName.startsWith(`app_${modelCamel}`) ||
                    // Direct model name patterns (for some model types)
                    fileBaseName === modelLower ||
                    fileBaseName === modelLower + 'd' ||
                    // Pattern matching with underscores/hyphens handled
                    (fileBaseName.replace(/[_-]/g, '') === modelLower.replace(/[_-]/g, '') ||
                     fileBaseName.replace(/[_-]/g, '') === modelLower.replace(/[_-]/g, '') + 'd');
                
                if (matchesPattern) {
                    outputFiles.executables.push({
                        name: file,
                        path: filePath,
                        size: stats.size,
                        sizeFormatted: formatFileSize(stats.size),
                        createdAt: stats.birthtime.toISOString()
                    });
                    logger.debug(`Found executable: ${file}`);
                }
            }
        }
        
        logger.info(`Found ${outputFiles.dlls.length} DLLs and ${outputFiles.executables.length} executables for ${modelName}`);
    } catch (error) {
        logger.error('Error finding output files:', error);
        logger.error('Error stack:', error.stack);
        // Don't throw - return empty result instead
    }
    
    return outputFiles;
}

/**
 * Copy output files to storage/outputs/{buildId}/
 * This creates a copy of the generated files for download purposes.
 * 
 * File locations:
 * - Copied DLLs: storage/outputs/{buildId}/dlls/{ModelName}.dll
 * - Copied EXEs: storage/outputs/{buildId}/executables/App_{ModelName}.exe
 * 
 * @param {string} buildId - Build ID
 * @param {object} outputFiles - Output files object with dlls and executables
 * @returns {Promise<object>} Copied files with new paths
 */
async function copyOutputFiles(buildId, outputFiles) {
    // Use absolute path for storage root
    const outputDir = path.resolve(config.storage.root, 'outputs', buildId);
    const dllDir = path.join(outputDir, 'dlls');
    const exeDir = path.join(outputDir, 'executables');
    
    await fs.ensureDir(dllDir);
    await fs.ensureDir(exeDir);
    
    const copiedFiles = {
        dlls: [],
        executables: []
    };
    
    // Copy DLLs
    for (const dll of outputFiles.dlls) {
        const destPath = path.join(dllDir, dll.name);
        await fs.copy(dll.path, destPath);
        copiedFiles.dlls.push({
            ...dll,
            path: destPath
        });
    }
    
    // Copy executables
    for (const exe of outputFiles.executables) {
        const destPath = path.join(exeDir, exe.name);
        await fs.copy(exe.path, destPath);
        copiedFiles.executables.push({
            ...exe,
            path: destPath
        });
    }
    
    return copiedFiles;
}

module.exports = {
    findOutputFiles,
    copyOutputFiles
};
